

const KEY='want-map-pwa-v2';const TRIP_KEY='want-map-trips-v1';
let data=JSON.parse(localStorage.getItem(KEY)||'{"places":[],"items":[]}');let trips=JSON.parse(localStorage.getItem(TRIP_KEY)||'[]');let map,markers=[],editing=null,mapAreaFilter=false,selectedTags=[],selectedItemTags=[];
const CATS={food:{label:'飲食店',genres:['カフェ・喫茶店','スイーツ','パン・ベーカリー','和食','洋食','中華','韓国料理','イタリアン','フレンチ','ラーメン','居酒屋','その他']},shopping:{label:'買い物',genres:['服・ファッション','コスメ・美容','雑貨','家具・インテリア','家電','本・文具','食品・食材','お土産','その他']},sightseeing:{label:'観光・スポット',genres:['観光名所','美術館・博物館','神社・寺','公園・自然','撮影スポット','エンタメ','その他']},hotel:{label:'ホテル・宿',genres:['ホテル','旅館','民宿・ゲストハウス','その他']},other:{label:'その他',genres:['その他']}};
function $(id){return document.getElementById(id)}function esc(s=''){return String(s).replace(/[&<>'"]/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[m]))}function uid(){return Date.now().toString(36)+Math.random().toString(36).slice(2,8)}function yen(n){return n?`¥${Number(n).toLocaleString('ja-JP')}`:'—'}function persist(){localStorage.setItem(KEY,JSON.stringify(data));render()}function persistTrips(){localStorage.setItem(TRIP_KEY,JSON.stringify(trips));renderTrips()}
function catOptions(sel=''){return '<option value="">カテゴリを選択</option>'+Object.entries(CATS).map(([k,v])=>`<option value="${k}" ${k===sel?'selected':''}>${v.label}</option>`).join('')}
function genreOptions(cat,sel=''){let gs=CATS[cat]?.genres||[];return '<option value="">選択してください</option>'+gs.map(g=>`<option ${g===sel?'selected':''}>${esc(g)}</option>`).join('')}
function fillFilter(id){$(id).innerHTML='<option value="">カテゴリすべて</option>'+Object.entries(CATS).map(([k,v])=>`<option value="${k}">${v.label}</option>`).join('')}
function initMap(){map=L.map('map').setView([35.6812,139.7671],11);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© OpenStreetMap contributors'}).addTo(map);renderMap()}
function markerIcon(p){let emoji='';return L.divIcon({className:'',html:`<div class="pin"><span></span></div>`,iconSize:[34,34],iconAnchor:[17,34],popupAnchor:[0,-30]})}
function filteredPlaces(extraArea=false){let q=($('mapQ')?.value||'').toLowerCase(),cat=$('mapCat')?.value||'',status=$('mapStatus')?.value||'';return data.places.filter(p=>{let its=data.items.filter(i=>i.placeId===p.id);let hay=[p.name,p.address,p.city,p.area,p.genre,p.note,p.stationName,...(p.lines||[]),...(p.tags||[]),...its.map(i=>i.name),...its.map(i=>i.note)].join(' ').toLowerCase();let ok=(!q||hay.includes(q))&&(!cat||p.category===cat)&&(!status||p.status===status)&&(!selectedTags.length||selectedTags.every(tag=>(p.tags||[]).includes(tag)));if(extraArea&&map&&p.lat&&p.lng)ok=ok&&map.getBounds().contains([p.lat,p.lng]);return ok})}
function renderMap(){if(!map)return;markers.forEach(m=>m.remove());markers=[];let arr=filteredPlaces(mapAreaFilter);arr.forEach(p=>{if(p.lat&&p.lng){let m=L.marker([p.lat,p.lng],{icon:markerIcon(p)}).addTo(map).bindPopup(`<b>${esc(p.name)}</b><br>${esc(CATS[p.category]?.label||'')} ${p.genre?'・'+esc(p.genre):''}<br>${esc(p.address||'')}${p.price?'<br>'+yen(p.price):''}<br><button class="btn small" onclick="openPlace('${p.id}')">編集</button>`);markers.push(m)}});renderMapCards(arr)}
function renderMapCards(arr=filteredPlaces(mapAreaFilter)){$('mapCards').innerHTML=arr.length?arr.map(placeCard).join(''):'<div class="empty">この条件の場所はありません。</div>'}
function openAppleMap(id){let p=data.places.find(x=>x.id===id);if(!p)return;let hasCoords=!!(p.lat&&p.lng);let q=hasCoords?[p.name,p.address,[p.city,p.area].filter(Boolean).join(' ')].filter(Boolean).join(', '):[p.address,p.city,p.area].filter(Boolean).join(' ');if(!q)q=p.name||'';let ios=/iPhone|iPad|iPod/i.test(navigator.userAgent);let url=ios?(hasCoords?'maps://?ll='+encodeURIComponent(p.lat+','+p.lng)+'&q='+encodeURIComponent(q):'maps://?q='+encodeURIComponent(q)):(hasCoords?'https://maps.apple.com/?ll='+encodeURIComponent(p.lat+','+p.lng)+'&q='+encodeURIComponent(q):'https://maps.apple.com/?address='+encodeURIComponent(q));window.location.href=url}

function placeCard(p){let its=data.items.filter(i=>i.placeId===p.id);let stars='★'.repeat(Number(p.priority||0))+'☆'.repeat(3-Number(p.priority||0));let photo=p.photos?.[0]||'';let rawAddress=String(p.address||'').trim();let fallbackAddress=[p.city,p.area].filter(Boolean).join(' / ');let displayAddress=(rawAddress&&rawAddress!=='住所未登録')?rawAddress:fallbackAddress;let hasMap=!!(displayAddress||((p.lat||p.lng)&&p.name));let hasCoords=!!(p.lat&&p.lng);return `<div class="card"><div class="place-head"><div class="place-main"><div class="place-name">${esc(p.name)}</div>${p.anywhere?`<span class="anywhere-badge">どこでもいい${p.anywhereType==='genre'?'・ジャンル':'・お店'}</span>`:''}${hasMap?`<div class="address-row"><button type="button" class="address-link" aria-label="Appleマップで開く" title="Appleマップで開く" onclick="openAppleMap('${p.id}')"><span class="meta address-text">${esc(displayAddress||'地図で開く')}</span><span class="address-arrow" aria-hidden="true">›</span></button>${displayAddress&&!hasCoords?`<div class="meta" style="font-size:10px;margin-top:3px">Want Mapの地図には表示されません（住所のみ登録）</div>`:''}</div>`:`<div class="address-row"><span class="meta address-text">住所未登録</span></div>`}</div><div class="place-side"><span class="status ${p.status==='done'?'done':p.status==='again'?'again':''}">${p.status==='done'?'行った':p.status==='again'?'また行きたい':'行きたい'}</span>${photo?`<img class="place-photo photo-click" onclick="openPhoto('${photo}')" src="${photo}" alt=""><span class="photo-count">写真 ${p.photos.length}枚</span>`:''}</div></div><div class="chips"><span class="chip">${esc(CATS[p.category]?.label||'その他')}</span>${p.genre?`<span class="chip">${esc(p.genre)}</span>`:''}<span class="chip priority">${stars}</span>${p.price?`<span class="chip">予算 ${yen(p.price)}</span>`:''}</div>${p.stationName?`<div class="meta">最寄り駅：${esc(p.stationName)}${p.stationDistance?`（約${Math.round(p.stationDistance)}m）`:''}</div>`:''}${p.lines?.length?`<div class="meta">沿線：${p.lines.map(esc).join(' / ')}</div>`:''}${window.userLocation&&p.lat&&p.lng?`<div class="meta">現在地から約${Math.round(distM(window.userLocation.lat,window.userLocation.lng,p.lat,p.lng)).toLocaleString()}m</div>`:''}${p.visitedAt?`<div class="meta">訪問日：${esc(p.visitedAt)}</div>`:''}${deadlineHtml(p.deadline)}${p.note?`<div class="meta">${esc(p.note)}</div>`:''}${(p.tags||[]).length?`<div class="chips">${p.tags.map(t=>`<span class="chip tag-chip">#${esc(t)}</span>`).join('')}</div>`:''}${urlHtml(p.urls)}<div class="chips">${its.length?its.map(i=>`<button type="button" class="chip linked-item" onclick="openItem('${i.id}')"><span class="type-badge">${i.type==='buy'?'買いたい':i.type==='eat'?'食べたい':'やりたい'}</span>${esc(i.name)}${i.price?' ・ '+yen(i.price):''}${i.status==='done'?' ✓':''}</button>`).join(''):'<span class="meta">やりたいこと未登録</span>'}</div><div class="toolbar">${p.anywhere?`<button class="btn primary" onclick="searchAnywhere('${p.id}')">近くで探す</button>`:''}<button class="btn" onclick="toggleToday('${p.id}')">${p.today?'今日から外す':'今日行く'}</button><button class="btn" onclick="openItem(null,'${p.id}')">＋ したい・ほしい</button><button class="btn" onclick="openPlace('${p.id}')">編集</button><button class="btn danger" onclick="delPlace('${p.id}')">削除</button></div></div>`}

function openPlace(id=null){editing={kind:'place',id};let p=id?data.places.find(x=>x.id===id):{status:'want',priority:1};$('modalTitle').textContent=id?'場所を編集':'行きたい場所を追加';$('modalBody').innerHTML=`<form id="placeForm" class="form"><div><div class="label">店名・スポット名 *</div><input class="input" name="name" value="${esc(p.name||'')}" placeholder="例：ダイソー、カフェ、本屋" required></div><div class="label">登録方法</div><div class="row"><label class="chip" style="padding:10px;cursor:pointer"><input type="radio" name="locationMode" value="fixed" ${!p.anywhere?'checked':''}> 場所を指定</label><label class="chip" style="padding:10px;cursor:pointer"><input type="radio" name="locationMode" value="anywhere" ${p.anywhere?'checked':''}> どこでもいい</label></div><div id="fixedLocationFields" style="display:${p.anywhere?'none':'block'}"><div class="label">場所名・住所</div><div class="search-row"><input class="input" id="address" name="address" value="${esc(p.address||'')}" placeholder="住所を入力（例：東京都渋谷区○○1-2-3）"><button type="button" class="btn primary geo-search-btn" id="geoBtn"><span class="ico ico-search"></span> 検索</button></div><div class="geo-help">住所を入力して検索できます。住所を空欄にしても、上の「場所名」から検索できます。候補を選ばなくても、保存時に先頭候補を自動取得します。</div><button type="button" class="btn" id="pickMapBtn">📍 地図から位置を指定</button><div id="geo" class="geo-status"></div><div id="geoResults" class="geo-results"></div></div></div><div id="anywhereHelp" class="geo-help" style="display:${p.anywhere?'block':'none'}">住所を決めずに登録できます。「どのお店でもいい」のか「このジャンルならどこでもいい」のかを選べます。</div><div id="anywhereType" class="anywhere-type" style="display:${p.anywhere?'block':'none'}"><div class="anywhere-type-title">「どこでもいい」の種類</div><div class="row"><label class="chip" style="padding:10px;cursor:pointer"><input type="radio" name="anywhereType" value="shop" ${p.anywhereType!=='genre'?'checked':''}> このお店ならどこでもいい</label><label class="chip" style="padding:10px;cursor:pointer"><input type="radio" name="anywhereType" value="genre" ${p.anywhereType==='genre'?'checked':''}> このジャンルならどこでもいい</label></div><div class="geo-help" style="margin:6px 0 0">例：「ダイソー」はお店、「本屋」はジャンル。ジャンルの場合も、あとから同じように「買いたい・食べたい」を紐付けられます。</div></div><div class="row"><div><div class="label">カテゴリ *</div><select class="select" id="category" name="category" required>${catOptions(p.category||'')}</select></div><div><div class="label">ジャンル</div><select class="select" id="genre" name="genre">${genreOptions(p.category||'',p.genre||'')}</select></div></div><div class="row"><div><div class="label">ステータス</div><select class="select" name="status"><option value="want" ${p.status==='want'||!p.status?'selected':''}>行きたい</option><option value="done" ${p.status==='done'?'selected':''}>行った</option><option value="again" ${p.status==='again'?'selected':''}>また行きたい</option></select></div><div><div class="label">行った日</div><input class="input date-input" type="date" name="visitedAt" value="${p.visitedAt||''}"></div></div><div class="row"><div><div class="label">優先度</div><select class="select" name="priority"><option value="0" ${p.priority==0?'selected':''}>☆ なし</option><option value="1" ${p.priority==1?'selected':''}>★</option><option value="2" ${p.priority==2?'selected':''}>★★</option><option value="3" ${p.priority==3?'selected':''}>★★★</option></select></div></div><div class="deadline-place-field"><div class="label">期限</div><input class="input date-input" type="date" name="deadline" value="${p.deadline||''}"></div><div><div class="label">最寄り駅・路線</div><button type="button" class="btn" id="stationBtn">最寄り駅を調べる</button><div id="stationStatus" class="geo-status"></div></div><div><div class="label">価格・予算（円）</div><input class="input" type="number" min="0" name="price" value="${p.price||''}" placeholder="例：5000"></div><div><div class="label">旅行に追加</div><select class="select" name="tripId"><option value="">旅行を選択しない</option>${trips.map(t=>`<option value="${t.id}" ${p.tripId===t.id?'selected':''}>${esc(t.name)}</option>`).join('')}</select></div><div><div class="label">タグ</div><input type="hidden" name="tags" id="placeTags" value="${esc((p.tags||[]).join(', '))}"><div id="placeTagPicker"></div><div class="tag-help">過去に使ったタグから選択できます。複数選択OK。</div></div><div><div class="label">URL</div><div id="placeUrls" class="url-fields"></div><button type="button" class="btn" onclick="addUrlField('placeUrls')">＋ URLを追加</button></div><div><div class="label">メモ</div><textarea class="textarea" name="note" placeholder="予約・注意点・一緒に行く人など">${esc(p.note||'')}</textarea></div><div><div class="label">写真（複数可）</div><input class="input" type="file" id="placePhotos" accept="image/*" multiple><div id="placePhotosPreview" class="photos">${(p.photos||[]).map((s,i)=>`<div class="photo-box"><img class="photo-preview" src="${s}"><button type="button" onclick="removeTempPhoto(${i})">×</button></div>`).join('')}</div></div><div class="actions"><button type="button" class="btn" onclick="closeModal()">キャンセル</button><button class="btn primary">保存</button></div></form>`;$('modal').classList.add('show');bindPlaceForm(p);setupTagPicker('place',p.tags||[]);(p.urls||[]).forEach(u=>addUrlField('placeUrls',u.label,u.url));if(p.lat&&p.lng){$('geo').textContent='✓ 登録済みの地図位置があります';$('geo').className='geo-status ok';$('address').dataset.selectedGeo=JSON.stringify({lat:p.lat,lng:p.lng,city:p.city||'',area:p.area||''});if(p.stationName){let r={stationName:p.stationName,stationDistance:p.stationDistance||0,lines:p.lines||[]};$('stationStatus').dataset.result=JSON.stringify(r);$('stationStatus').textContent=`✓ ${p.stationName}${p.stationDistance?`（約${Math.round(p.stationDistance)}m）`:''}${p.lines?.length?' / '+p.lines.join('・'):''}`;$('stationStatus').className='geo-status ok'}}}
let locationPickerMap=null,locationPickerMarker=null,locationPickerPoint=null,locationPickerOld=null;
function openLocationPicker(){let addr=$('address'),selected=addr?.dataset.selectedGeo?JSON.parse(addr.dataset.selectedGeo):null;locationPickerOld=selected||null;let center=selected?[selected.lat,selected.lng]:(addr?.value&&map?map.getCenter():map?map.getCenter():[35.6812,139.7671]);$('locationPicker').classList.add('show');setTimeout(()=>{if(!locationPickerMap){locationPickerMap=L.map('locationPickerMap').setView(center,selected?17:15);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; OpenStreetMap contributors'}).addTo(locationPickerMap);locationPickerMap.on('click',e=>setPickerPoint(e.latlng.lat,e.latlng.lng));}else{locationPickerMap.invalidateSize();locationPickerMap.setView(center,selected?17:15)}if(selected)setPickerPoint(selected.lat,selected.lng);else clearPickerPoint()},120)}
function setPickerPoint(lat,lng){locationPickerPoint={lat:Number(lat),lng:Number(lng)};if(locationPickerMarker){locationPickerMarker.setLatLng([locationPickerPoint.lat,locationPickerPoint.lng])}else{locationPickerMarker=L.marker([locationPickerPoint.lat,locationPickerPoint.lng],{draggable:true,icon:L.divIcon({className:'',html:'<div class="location-picker-marker"></div>',iconSize:[30,30],iconAnchor:[15,30]})}).addTo(locationPickerMap);locationPickerMarker.on('dragend',()=>{let x=locationPickerMarker.getLatLng();locationPickerPoint={lat:x.lat,lng:x.lng};updatePickerStatus()})}updatePickerStatus()}
function clearPickerPoint(){locationPickerPoint=null;if(locationPickerMarker){locationPickerMarker.remove();locationPickerMarker=null}updatePickerStatus()}
function updatePickerStatus(){$('locationPickerStatus').textContent=locationPickerPoint?`指定位置：${locationPickerPoint.lat.toFixed(6)}, ${locationPickerPoint.lng.toFixed(6)}`:'位置を指定してください。'}
function closeLocationPicker(){$('locationPicker').classList.remove('show')}
async function reverseGeocodePickedLocation(){if(!locationPickerPoint){alert('先に地図上でピンの位置を指定してください。');return}let lat=locationPickerPoint.lat,lng=locationPickerPoint.lng;let status=$('locationPickerStatus');status.textContent='住所を検索中…';try{let url='https://nominatim.openstreetmap.org/reverse?format=jsonv2&lat='+encodeURIComponent(lat)+'&lon='+encodeURIComponent(lng)+'&zoom=18&addressdetails=1&accept-language=ja';let r=await fetch(url,{headers:{'Accept':'application/json'}});if(!r.ok)throw new Error('HTTP '+r.status);let x=await r.json();let address=String(x.display_name||'').trim();if(!address){status.textContent='住所が見つかりませんでした。';return}let ad=x.address||{};let city=ad.city||ad.town||ad.village||ad.municipality||'';let area=ad.suburb||ad.neighbourhood||ad.quarter||ad.city_district||'';let ok=confirm(`この住所を登録しますか？\n\n${address}`);if(!ok){status.textContent='位置を指定してください。';return}let addr=$('address');let old=addr.dataset.selectedGeo?JSON.parse(addr.dataset.selectedGeo):{};let geo={...old,lat,lng,city,area,address};addr.value=address;addr.dataset.selectedGeo=JSON.stringify(geo);delete addr.dataset.manualAddress;$('geo').textContent='✓ ピンの位置から住所を登録しました';$('geo').className='geo-status ok';$('stationStatus').textContent='最寄り駅を取得中…';$('stationStatus').className='geo-status';delete $('stationStatus').dataset.result;closeLocationPicker();await lookupStation(lat,lng)}catch(e){status.textContent='住所の取得に失敗しました。通信状態を確認してください。'}}
function applyPickedLocation(){if(!locationPickerPoint){alert('地図上で位置を指定してください。');return}let addr=$('address');let old=addr.dataset.selectedGeo?JSON.parse(addr.dataset.selectedGeo):{};let geo={...old,lat:locationPickerPoint.lat,lng:locationPickerPoint.lng};if(!geo.address)geo.address=addr.value.trim();addr.dataset.selectedGeo=JSON.stringify(geo);$('geo').textContent='✓ 地図上の位置を指定しました';$('geo').className='geo-status ok';$('stationStatus').textContent='位置を確定後、最寄り駅を取得できます。';$('stationStatus').className='geo-status';delete $('stationStatus').dataset.result;closeLocationPicker();lookupStationForForm()}
function useCurrentLocationForPicker(){if(!navigator.geolocation){alert('現在地を取得できません。');return}navigator.geolocation.getCurrentPosition(pos=>{let lat=pos.coords.latitude,lng=pos.coords.longitude;if(locationPickerMap){locationPickerMap.setView([lat,lng],18);setPickerPoint(lat,lng)}},()=>alert('現在地を取得できませんでした。'))}

function bindPlaceForm(old){let cat=$('category'),genre=$('genre');cat.onchange=()=>genre.innerHTML=genreOptions(cat.value);document.querySelectorAll('input[name=locationMode]').forEach(r=>r.onchange=()=>{let any=r.value==='anywhere'&&r.checked;if($('fixedLocationFields'))$('fixedLocationFields').style.display=any?'none':'block';if($('anywhereHelp'))$('anywhereHelp').style.display=any?'block':'none';if($('anywhereType'))$('anywhereType').style.display=any?'block':'none';let a=$('address');if(a)a.required=!any});let initAny=!!old.anywhere;if($('address'))$('address').required=false;$('geoBtn').onclick=()=>searchAddress();$('pickMapBtn').onclick=()=>openLocationPicker();$('stationBtn').onclick=()=>lookupStationForForm();$('address').addEventListener('input',()=>{delete $('address').dataset.selectedGeo;delete $('address').dataset.manualAddress;});document.querySelector('#placeForm [name="name"]')?.addEventListener('input',()=>delete $('address').dataset.selectedGeo);$('address').addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();searchAddress()}});$('placePhotos').addEventListener('change',e=>readFiles(e.target.files,'placePhotosPreview',old.photos||[]));$('placeForm').onsubmit=async e=>{e.preventDefault();let f=new FormData(e.target),isAnywhere=f.get('locationMode')==='anywhere',addr=String(f.get('address')||'').trim(),selected=$('address').dataset.selectedGeo?JSON.parse($('address').dataset.selectedGeo):null;let geo=selected;if(!isAnywhere&&!geo){geo=await searchAddress(true);if(!geo){$('geo').textContent='場所名または住所を検索して、位置を取得してください。';$('geo').className='geo-status err';return}}let photos=await collectPhotos(old.photos||[],'placePhotosPreview');let status=f.get('status'),visitedAt=f.get('visitedAt')||'';if(status==='done'&&!visitedAt)visitedAt=new Date().toISOString().slice(0,10);let isManualAddress=!!geo?.manual;let station=(old.stationName&&!isManualAddress)?{stationName:old.stationName,stationDistance:old.stationDistance,lines:old.lines||[]}:{};if(!isManualAddress&&$('stationStatus')?.dataset.result)station=JSON.parse($('stationStatus').dataset.result);let x={name:f.get('name').trim(),anywhere:isAnywhere,anywhereType:isAnywhere?(f.get('anywhereType')||old.anywhereType||'shop'):'',address:isAnywhere?'':(geo?.address||addr),category:f.get('category'),genre:f.get('genre'),status,priority:Number(f.get('priority')||0),visitedAt,deadline:f.get('deadline')||'',favorite:f.get('favorite')==='on',price:Number(f.get('price')||0),tripId:f.get('tripId')||'',tags:normalizeTags(f.get('tags')||''),urls:collectUrls('placeUrls'),note:f.get('note')||'',photos,lat:isAnywhere?(old.lat??null):(isManualAddress?null:(geo?.lat??old.lat??null)),lng:isAnywhere?(old.lng??null):(isManualAddress?null:(geo?.lng??old.lng??null)),city:isAnywhere?'':(geo?.city??(isManualAddress?'':old.city??'')),area:isAnywhere?'':(geo?.area??(isManualAddress?'':old.area??'')),stationName:isAnywhere?(old.stationName||''):(isManualAddress?'':(station.stationName||'')),stationDistance:isAnywhere?(old.stationDistance||0):(isManualAddress?0:(station.stationDistance||0)),lines:isAnywhere?(old.lines||[]):(isManualAddress?[]:(station.lines||[])),today:old.today||false};let nn=normalizeText(x.name),na=normalizeText(x.address);let dup=data.places.find(z=>z.id!==editing.id&&((nn&&normalizeText(z.name)===nn)||(na&&normalizeText(z.address)===na)));if(dup&&!confirm(`似た場所がすでに登録されています。\n\n${dup.name}${dup.address?'\n'+dup.address:''}\n\nこのまま登録しますか？`))return;if(editing.id)Object.assign(data.places.find(p=>p.id===editing.id),x);else data.places.push({id:uid(),...x});closeModal();persist()}}
async function searchAddress(autoPick=false){let addr=$('address')?.value.trim(),name=document.querySelector('#placeForm [name="name"]')?.value.trim();if(!addr&&!name){$('geo').textContent='場所名または住所を入力してください。';$('geo').className='geo-status err';return null;}$('geo').textContent='場所を検索中…';$('geo').className='geo-status';$('geoResults').innerHTML='';try{let q=[name,addr].filter(Boolean).join(', ');let url='https://nominatim.openstreetmap.org/search?format=jsonv2&limit=5&addressdetails=1&accept-language=ja&q='+encodeURIComponent(q);let r=await fetch(url,{headers:{'Accept':'application/json'}});if(!r.ok)throw new Error('HTTP '+r.status);let a=await r.json();if(!a.length&&name&&addr){url='https://nominatim.openstreetmap.org/search?format=jsonv2&limit=5&addressdetails=1&accept-language=ja&q='+encodeURIComponent(addr);r=await fetch(url,{headers:{'Accept':'application/json'}});a=await r.json()}if(!a.length){if(addr){$('address').dataset.manualAddress=addr;$('geo').textContent='候補が見つかりませんでした。入力した住所をそのまま登録できます。';$('geo').className='geo-status ok';return autoPick?{lat:null,lng:null,city:'',area:'',address:addr,manual:true}:null}$('geo').textContent='候補が見つかりませんでした。場所名または住所を入力してください。';$('geo').className='geo-status err';return null}if(autoPick){let x=a[0],ad=x.address||{};let geo={lat:Number(x.lat),lng:Number(x.lon),city:ad.city||ad.town||ad.village||ad.municipality||'',area:ad.suburb||ad.neighbourhood||ad.quarter||ad.city_district||'',address:x.display_name||addr||name||''};$('address').value=geo.address;$('address').dataset.selectedGeo=JSON.stringify(geo);$('geo').textContent='✓ 住所と地図上の位置を取得しました';$('geo').className='geo-status ok';await lookupStation(geo.lat,geo.lng);return geo}$('geo').textContent=`候補が${a.length}件見つかりました。正しい場所を選択してください。`;$('geo').className='geo-status ok';$('geoResults').innerHTML=a.map((x,i)=>`<button type="button" class="geo-result" onclick="selectGeo(${i})"><b>${esc(x.name||'候補')}</b><span>${esc(x.display_name||'')}</span></button>`).join('');window._geoCandidates=a;return null}catch(e){$('geo').textContent='位置検索に失敗しました。通信状態を確認してください。';$('geo').className='geo-status err';return null}}
function selectGeo(i){let x=window._geoCandidates?.[i];if(!x)return;let ad=x.address||{};let geo={lat:Number(x.lat),lng:Number(x.lon),city:ad.city||ad.town||ad.village||ad.municipality||'',area:ad.suburb||ad.neighbourhood||ad.quarter||ad.city_district||'',address:x.display_name||''};$('address').value=geo.address;$('address').dataset.selectedGeo=JSON.stringify(geo);$('geoResults').innerHTML='';$('geo').textContent='✓ 住所と地図上の位置を取得しました';$('geo').className='geo-status ok';lookupStation(geo.lat,geo.lng)}
async function lookupStationForForm(){let g=$('address')?.dataset.selectedGeo;if(!g){$('stationStatus').textContent='先に住所を検索して候補を選択してください。';$('stationStatus').className='geo-status err';return}let geo=JSON.parse(g);await lookupStation(geo.lat,geo.lng)}
async function lookupStation(lat,lng){let el=$('stationStatus');if(!el)return;el.textContent='最寄り駅・路線を検索中…';el.className='geo-status';try{let q=`[out:json][timeout:20];node(around:1800,${lat},${lng})[railway~"^(station|halt)$"];out body;`;let r=await fetch('https://overpass-api.de/api/interpreter?data='+encodeURIComponent(q));if(!r.ok)throw new Error('station '+r.status);let a=(await r.json()).elements||[];if(!a.length){el.textContent='近くの駅が見つかりませんでした。';el.className='geo-status err';return}a.sort((x,y)=>distM(lat,lng,Number(x.lat),Number(x.lon))-distM(lat,lng,Number(y.lat),Number(y.lon)));let st=a[0],distance=distM(lat,lng,Number(st.lat),Number(st.lon));let q2=`[out:json][timeout:20];node(${st.id});rel(bn)["type"="route"]["route"~"^(train|subway|tram|light_rail|monorail)$"];out tags;`;let r2=await fetch('https://overpass-api.de/api/interpreter?data='+encodeURIComponent(q2));let rels=r2.ok?(await r2.json()).elements||[]:[];let lines=[...new Set(rels.map(x=>x.tags?.name||x.tags?.ref).filter(Boolean))];let result={stationName:st.tags?.name||'最寄り駅',stationDistance:distance,lines};el.dataset.result=JSON.stringify(result);el.textContent=`✓ ${result.stationName}（約${Math.round(distance)}m）${lines.length?' / '+lines.join('・'):''}`;el.className='geo-status ok'}catch(e){el.textContent='駅・路線の検索に失敗しました。後から再検索できます。';el.className='geo-status err'}}
function distM(a,b,c,d){let R=6371000,to=x=>x*Math.PI/180,da=to(c-a),db=to(d-b),x=Math.sin(da/2)**2+Math.cos(to(a))*Math.cos(to(c))*Math.sin(db/2)**2;return 2*R*Math.asin(Math.sqrt(x))}
function readFiles(files,previewId,existing){let box=$(previewId);[...files].forEach(file=>{let r=new FileReader();r.onload=()=>{let d=document.createElement('div');d.className='photo-box';d.dataset.temp=r.result;d.innerHTML=`<img class="photo-preview" src="${r.result}"><button type="button">×</button>`;d.querySelector('button').onclick=()=>d.remove();box.appendChild(d)};r.readAsDataURL(file)})}
async function collectPhotos(existing,previewId){let arr=[];document.querySelectorAll('#'+previewId+' .photo-box').forEach(b=>arr.push(b.dataset.temp||b.querySelector('img')?.src));return arr.filter(Boolean)}
function removeTempPhoto(i){let boxes=document.querySelectorAll('#placePhotosPreview .photo-box');if(boxes[i])boxes[i].remove()}
function openItem(id=null,placeId=''){editing={kind:'item',id};let i=id?data.items.find(x=>x.id===id):{type:'buy',placeId:placeId||'',status:'want'};$('modalTitle').textContent=id?'リストを編集':'したい・ほしいを追加';$('modalBody').innerHTML=`<form id="itemForm" class="form"><div><div class="label">内容 *</div><input class="input" name="name" value="${esc(i.name||'')}" placeholder="例：クロッフル、コスメ" required></div><div class="row"><div><div class="label">種類</div><select class="select" name="type"><option value="buy" ${i.type==='buy'?'selected':''}>買いたい</option><option value="eat" ${i.type==='eat'?'selected':''}>食べたい</option><option value="do" ${i.type==='do'?'selected':''}>やりたい</option></select></div><div><div class="label">場所 <span style="font-size:10px">（任意）</span></div><select class="select" name="placeId"><option value="" ${!i.placeId?'selected':''}>場所を設定しない</option>${data.places.map(p=>`<option value="${p.id}" ${i.placeId===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select><div class="hint">あとから場所を追加・変更できます。</div></div></div><div class="row"><div><div class="label">価格・予算（円）</div><input class="input" type="number" min="0" name="price" value="${i.price||''}" placeholder="例：3000"></div><div><div class="label">ステータス</div><select class="select" name="status"><option value="want" ${i.status!=='done'?'selected':''}>行きたい</option><option value="done" ${i.status==='done'?'selected':''}>済み</option></select></div></div><div><div class="label">期限</div><input class="input date-input" type="date" name="deadline" value="${i.deadline||''}"></div><div><div class="label">タグ</div><input type="hidden" name="tags" id="itemTags" value="${esc((i.tags||[]).join(', '))}"><div id="itemTagPicker"></div><div class="tag-help">過去に使ったタグから選択できます。複数選択OK。</div></div><div><div class="label">メモ</div><textarea class="textarea" name="note">${esc(i.note||'')}</textarea></div><div><div class="label">URL</div><div id="itemUrls" class="url-fields"></div><button type="button" class="btn" onclick="addUrlField('itemUrls')">＋ URLを追加</button></div><div><div class="label">写真</div><input class="input" type="file" name="photo" accept="image/*"><div class="photos">${i.photo?`<img class="photo-preview" src="${i.photo}">`:''}</div></div><div class="actions"><button type="button" class="btn" onclick="closeModal()">キャンセル</button><button class="btn primary">保存</button></div></form>`;$('modal').classList.add('show');setupTagPicker('item',i.tags||[]);(i.urls||[]).forEach(u=>addUrlField('itemUrls',u.label,u.url));$('itemForm').onsubmit=async e=>{e.preventDefault();let f=new FormData(e.target),old=id?data.items.find(x=>x.id===id):{},photo=old.photo||null,file=f.get('photo');if(file&&file.size)photo=await fileToData(file);let x={name:f.get('name').trim(),type:f.get('type'),placeId:f.get('placeId')||'',price:Number(f.get('price')||0),status:f.get('status'),deadline:f.get('deadline')||'',tags:normalizeTags(f.get('tags')||''),favorite:id?!!old.favorite:false,note:f.get('note')||'',urls:collectUrls('itemUrls'),photo};if(id)Object.assign(old,x);else data.items.push({id:uid(),...x});closeModal();persist()}}

function fileToData(file){return new Promise((res,rej)=>{let r=new FileReader();r.onload=()=>res(r.result);r.onerror=rej;r.readAsDataURL(file)})}
function toggleItemDone(id,checked){let i=data.items.find(x=>x.id===id);if(!i)return;i.status=checked?'done':'want';persist()}
function delPlace(id){if(confirm('この場所を削除しますか？\n\n紐づいているリストは削除せず、場所未設定にします。')){data.places=data.places.filter(p=>p.id!==id);data.items.forEach(i=>{if(i.placeId===id)i.placeId=''});persist()}}function delItem(id){if(confirm('削除しますか？')){data.items=data.items.filter(i=>i.id!==id);persist()}}
function toggleToday(id){let p=data.places.find(x=>x.id===id);if(!p)return;p.today=!p.today;persist()}
function moveToday(id,dir){let idx=data.places.findIndex(p=>p.id===id);if(idx<0)return;let ids=data.places.map(p=>p.id);let todayIdxs=ids.filter(x=>data.places.find(p=>p.id===x)?.today);let pos=todayIdxs.indexOf(id),next=pos+dir;if(pos<0||next<0||next>=todayIdxs.length)return;let swapId=todayIdxs[next],j=data.places.findIndex(p=>p.id===swapId);[data.places[idx],data.places[j]]=[data.places[j],data.places[idx]];persist();openTodayPanel()}
function openTodayPanel(){let ps=data.places.filter(p=>p.today);$('todayPanel').style.display='block';$('todayPanel').innerHTML=`<div style="font-weight:750">今日行く場所 ${ps.length}件</div>${ps.length?`<div class="today-list">${ps.map((p,i)=>`<div class="today-row"><span>${i+1}</span><span class="name">${esc(p.name)}</span><span class="meta">${esc(p.stationName||'')}</span><button class="btn small" onclick="moveToday('${p.id}',-1)">↑</button><button class="btn small" onclick="moveToday('${p.id}',1)">↓</button><button class="btn small" onclick="openPlace('${p.id}')">詳細</button><button class="btn small" onclick="toggleToday('${p.id}')">外す</button></div>`).join('')}</div><div class="toolbar"><button class="btn primary" onclick="openRoute()">ルートを作る</button><button class="btn" onclick="clearToday()">今日を全て外す</button></div>`:'<div class="empty" style="padding:16px">まだ「今日行く」場所がありません。</div>'}`;}
function clearToday(){data.places.forEach(p=>p.today=false);persist();openTodayPanel()}
function openRoute(){let ps=data.places.filter(p=>p.today&&p.lat&&p.lng);if(!ps.length){alert('今日行く場所に地図位置がある場所を追加してください。');return}let origin=ps[0],dest=ps[ps.length-1],way=ps.slice(1,-1);let url='https://www.google.com/maps/dir/?api=1&origin='+encodeURIComponent(origin.lat+','+origin.lng)+'&destination='+encodeURIComponent(dest.lat+','+dest.lng)+(way.length?'&waypoints='+encodeURIComponent(way.map(p=>p.lat+','+p.lng).join('|')):'')+'&travelmode=transit';window.open(url,'_blank')}
async function searchAnywhere(id){let p=data.places.find(x=>x.id===id);if(!p||!p.anywhere)return;if(!navigator.geolocation){alert('この端末では現在地を取得できません。');return}navigator.geolocation.getCurrentPosition(async pos=>{let lat=pos.coords.latitude,lng=pos.coords.longitude;window.userLocation={lat,lng};$('modalTitle').textContent=`「${p.name}」を近くで探す`;$('modalBody').innerHTML='<div class="anywhere-panel"><div class="geo-status">近くの候補を検索中…</div></div>';$('modal').classList.add('show');try{let qn=String(p.name||'').replace(/["\\]/g,'');let q=`[out:json][timeout:25];(nwr(around:5000,${lat},${lng})[name~"${qn}",i];);out center tags;`;let r=await fetch('https://overpass-api.de/api/interpreter?data='+encodeURIComponent(q));if(!r.ok)throw new Error();let els=(await r.json()).elements||[];els=els.map(x=>{let y=x.center||x;return {...x,lat:Number(y.lat),lng:Number(y.lon),d:distM(lat,lng,Number(y.lat),Number(y.lon))}}).filter(x=>x.lat&&x.lng).sort((a,b)=>a.d-b.d).slice(0,12);if(!els.length){$('modalBody').innerHTML='<div class="anywhere-panel"><div class="geo-status err">近くに候補が見つかりませんでした。OpenStreetMapに登録されていない店舗は表示されない場合があります。</div><div class="actions"><button class="btn primary" onclick="closeModal()">閉じる</button></div></div>';return}$('modalBody').innerHTML=`<div class="anywhere-panel"><div class="manual-intro">現在地から近い順に表示しています。</div>${els.map((x,i)=>`<button type="button" class="anywhere-result" onclick="selectAnywhere('${p.id}',${x.lat},${x.lng},${JSON.stringify(x.tags?.name||p.name).replace(/'/g,"&#39;")})"><b>${esc(x.tags?.name||p.name)}</b><span class="meta">約${Math.round(x.d).toLocaleString()}m${x.tags?.['addr:street']?' ・ '+esc(x.tags['addr:street']):''}</span></button>`).join('')}<div class="actions"><button class="btn" onclick="closeModal()">閉じる</button></div></div>`}catch(e){$('modalBody').innerHTML='<div class="anywhere-panel"><div class="geo-status err">周辺検索に失敗しました。通信状態を確認してください。</div><div class="actions"><button class="btn primary" onclick="closeModal()">閉じる</button></div></div>'}},()=>alert('現在地を取得できませんでした。位置情報の許可を確認してください。'),{enableHighAccuracy:true,timeout:10000,maximumAge:60000})}
function selectAnywhere(id,lat,lng,name){let p=data.places.find(x=>x.id===id);if(!p)return;p.name=name||p.name;p.anywhere=false;p.lat=lat;p.lng=lng;p.address='';p.city='';p.area='';closeModal();persist();lookupStation(lat,lng)}
function showNearby(){if(!navigator.geolocation){alert('この端末では現在地を取得できません。');return}navigator.geolocation.getCurrentPosition(pos=>{window.userLocation={lat:pos.coords.latitude,lng:pos.coords.longitude};$('nearStatus').textContent='現在地から近い順で表示しています。';if($('placeSort'))$('placeSort').value='distance';renderPlaces();if(map){map.setView([window.userLocation.lat,window.userLocation.lng],14);L.circleMarker([window.userLocation.lat,window.userLocation.lng],{radius:7}).addTo(map).bindPopup('現在地').openPopup()}},()=>alert('現在地を取得できませんでした。位置情報の許可を確認してください。'),{enableHighAccuracy:true,timeout:10000,maximumAge:60000})}
function showStationSearch(){$('stationQuick').style.display=$('stationQuick').style.display==='none'?'block':'none';$('stationQ').focus()}
function applyStationSearch(){let q=($('stationQ').value||'').trim().toLowerCase();if(!q)return;$('placeQ').value=q;renderPlaces();$('stationQuick').style.display='block'}
function openPhoto(src){$('modalTitle').textContent='写真';$('modalBody').innerHTML=`<img class="photo-click" src="${src}" style="width:100%;max-height:70vh;object-fit:contain;border-radius:14px;background:#f5f5f5"><div class="actions"><button class="btn primary" onclick="closeModal()">閉じる</button></div>`;$('modal').classList.add('show')}
function deadlineState(v){if(!v)return '';let d=new Date(v+'T23:59:59');let now=new Date();let diff=Math.ceil((d-now)/86400000);return {date:v,diff,overdue:diff<0,soon:diff>=0&&diff<=7};}
function deadlineHtml(v){let x=deadlineState(v);if(!x)return '';let label=x.overdue?`期限切れ：${x.date}`:`期限：${x.date}`;return `<div class="deadline ${x.overdue?'overdue':x.soon?'soon':''}">${label}</div>`}
function toggleItemFavorite(id){let i=data.items.find(x=>x.id===id);if(!i)return;i.favorite=!i.favorite;persist()}
function deadlineMatch(v,mode){let x=deadlineState(v);if(mode==='set')return !!x;if(mode==='soon')return !!x&&!x.overdue&&x.soon;if(mode==='overdue')return !!x&&x.overdue;return true}
function normalizeText(v=''){return String(v).toLowerCase().replace(/[\s　]/g,'').replace(/[「」『』（）()［］\[\]・,，.。]/g,'')}
function safeUrl(v=''){let x=String(v).trim();if(!x)return '';if(!/^https?:\/\//i.test(x))x='https://'+x;try{let u=new URL(x);return /^https?:$/.test(u.protocol)?u.href:''}catch{return ''}}
function urlHtml(urls){let a=Array.isArray(urls)?urls:[];return a.length?`<div class="url-list">${a.map((u,i)=>{let href=safeUrl(u.url||u);if(!href)return '';let label=esc(u.label||'リンク');return `<a class="url-link" href="${esc(href)}" target="_blank" rel="noopener noreferrer" onclick="event.stopPropagation()">🔗 ${label}</a>`}).join('')}</div>`:''}
function collectUrls(containerId){let out=[];document.querySelectorAll('#'+containerId+' .url-field').forEach(row=>{let label=row.querySelector('[name=urlLabel]')?.value.trim()||'リンク';let url=safeUrl(row.querySelector('[name=url]')?.value||'');if(url)out.push({label,url})});return out}
function addUrlField(containerId,label='',url=''){let box=$(containerId);let d=document.createElement('div');d.className='url-field';d.innerHTML=`<input class="input" name="urlLabel" value="${esc(label)}" placeholder="名前（公式サイトなど）"><input class="input" name="url" value="${esc(url)}" placeholder="https://..."><button type="button" class="btn url-remove" onclick="this.parentElement.remove()">×</button>`;box.appendChild(d)}
function normalizeTag(t){return String(t||'').trim().replace(/^#+/,'').trim()}
function normalizeTags(value){let a=Array.isArray(value)?value:String(value||'').split(/[\n,]+/);let out=[];a.forEach(x=>{let t=normalizeTag(x);if(t&&!out.some(y=>y.toLowerCase()===t.toLowerCase()))out.push(t)});return out}
function allTags(){let arr=[];data.places.forEach(p=>(p.tags||[]).forEach(t=>arr.push(normalizeTag(t))));data.items.forEach(i=>(i.tags||[]).forEach(t=>arr.push(normalizeTag(t))));return [...new Set(arr.filter(Boolean))]}
function recentTags(){let seen=[];[...data.places].reverse().forEach(p=>(p.tags||[]).forEach(t=>{t=normalizeTag(t);if(t&&!seen.includes(t))seen.push(t)}));[...data.items].reverse().forEach(i=>(i.tags||[]).forEach(t=>{t=normalizeTag(t);if(t&&!seen.includes(t))seen.push(t)}));return seen.slice(0,8)}
function tagPickerHtml(prefix,selected){let vals=normalizeTags(selected);return `<div class="tag-control"><div class="tag-control-btn" role="button" tabindex="0" onclick="toggleTagMenu('${prefix}')" onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();toggleTagMenu('${prefix}')}"><div class="tag-selected" id="${prefix}Selected">${vals.length?vals.map(t=>`<span class="tag-chip-select">#${esc(t)} <button type="button" onclick="event.stopPropagation();removePickerTag('${prefix}',${JSON.stringify(t).replace(/</g,'\\u003c')})">×</button></span>`).join(''):'<span class="tag-placeholder">タグを選択</span>'}</div><span class="tag-chevron">⌄</span></div><div class="tag-menu" id="${prefix}Menu"><input class="tag-menu-search" id="${prefix}Search" placeholder="タグを検索…" oninput="renderTagPickerMenu('${prefix}')"><div id="${prefix}MenuBody"></div></div></div>`}
function setupTagPicker(prefix,selected){let hidden=$(prefix==='place'?'placeTags':'itemTags');if(!hidden)return;let vals=normalizeTags(selected);hidden.value=vals.join(', ');$(prefix==='place'?'placeTagPicker':'itemTagPicker').innerHTML=tagPickerHtml(prefix,vals);renderTagPickerMenu(prefix)}
function pickerSelected(prefix){let hidden=$(prefix==='place'?'placeTags':'itemTags');return normalizeTags(hidden?.value||'')}
function setPickerSelected(prefix,vals){let hidden=$(prefix==='place'?'placeTags':'itemTags');vals=normalizeTags(vals);hidden.value=vals.join(', ');let box=$(prefix+'Selected');if(box)box.innerHTML=vals.length?vals.map(t=>`<span class="tag-chip-select">#${esc(t)} <button type="button" onclick="event.stopPropagation();removePickerTag('${prefix}',${JSON.stringify(t).replace(/</g,'\u003c')})">×</button></span>`).join(''):'<span class="tag-placeholder">タグを選択</span>';renderTagPickerMenu(prefix)}
function togglePickerTag(prefix,tag){let vals=pickerSelected(prefix);let i=vals.findIndex(x=>x.toLowerCase()===String(tag).toLowerCase());if(i>=0)vals.splice(i,1);else vals.push(normalizeTag(tag));setPickerSelected(prefix,vals)}
function bindTagOptionClicks(prefix){let body=$(prefix+'MenuBody');if(!body)return;body.querySelectorAll('.tag-option[data-tag]').forEach(btn=>{btn.addEventListener('click',e=>{e.preventDefault();e.stopPropagation();togglePickerTag(prefix,btn.dataset.tag)})})}
