function toggleTagMenu(prefix){let menu=$(prefix+'Menu');if(!menu)return;document.querySelectorAll('.tag-menu.show').forEach(x=>{if(x!==menu)x.classList.remove('show')});menu.classList.toggle('show');if(menu.classList.contains('show')){$(prefix+'Search').value='';renderTagPickerMenu(prefix)}}
function renderTagPickerMenu(prefix){let menu=$(prefix+'Menu');if(!menu)return;let q=($(prefix+'Search')?.value||'').trim().toLowerCase(),sel=pickerSelected(prefix),all=allTags(),recent=recentTags().filter(t=>!q||t.toLowerCase().includes(q)),rest=all.filter(t=>!recent.includes(t)).filter(t=>!q||t.toLowerCase().includes(q));let html='';if(recent.length){html+='<div class="tag-menu-title">最近使ったタグ</div><div class="tag-options">'+recent.map(t=>{let on=sel.some(x=>x.toLowerCase()===t.toLowerCase());return `<button type="button" class="tag-option ${on?'selected':''}" data-tag="${esc(t)}">#${esc(t)}${on?' ✓':''}</button>`}).join('')+'</div>'}if(rest.length){html+='<div class="tag-menu-title">すべてのタグ</div><div class="tag-options">'+rest.map(t=>{let on=sel.some(x=>x.toLowerCase()===t.toLowerCase());return `<button type="button" class="tag-option ${on?'selected':''}" data-tag="${esc(t)}">#${esc(t)}${on?' ✓':''}</button>`}).join('')+'</div>'}if(!recent.length&&!rest.length)html='<div class="tag-empty">まだタグがありません。</div>';html+=`<div class="tag-create-row"><input id="${prefix}NewTag" placeholder="新しいタグを追加"><button type="button" onclick="createPickerTag('${prefix}')">＋追加</button></div>`;$(prefix+'MenuBody').innerHTML=html;bindTagOptionClicks(prefix)}
function createPickerTag(prefix){let el=$(prefix+'NewTag'),tag=normalizeTag(el?.value);if(!tag)return;let existing=allTags().find(t=>t.toLowerCase()===tag.toLowerCase());tag=existing||tag;let vals=pickerSelected(prefix);if(!vals.includes(tag))vals.push(tag);setPickerSelected(prefix,vals);if(el)el.value='';renderTagPickerMenu(prefix)}
function searchTagDropdownHtml(prefix,selected){let vals=selected||[],all=allTags(),recent=recentTags();return `<div class="tag-filter-wrap"><button type="button" class="tag-filter-btn ${vals.length?'active':''}" onclick="toggleSearchTagMenu('${prefix}')"><span>${vals.length?vals.map(t=>`#${esc(t)}`).join('　'):'タグで絞り込み'}</span><span>${vals.length?`<span class="tag-filter-count">${vals.length}件</span>`:'⌄'}</span></button><div class="tag-menu" id="${prefix}SearchMenu"><input class="tag-menu-search" id="${prefix}SearchTagInput" placeholder="タグを検索…" oninput="renderSearchTagMenu('${prefix}')"><div id="${prefix}SearchMenuBody"></div></div></div>`}
